<?php
class CxMovementRequest {private $data;function __construct($data){$this->data=$data;}function getParam($key){return $this->data[$key]??null;}}
class CxMovementResponse {public $data,$status=200;function withJson($data,$status=200){$this->data=$data;$this->status=$status;return $this;}}
trait CxMaterials {
    private function erpInsert($table,array $values) {
        $q=$this->db->prepare('INSERT INTO '.$table.' (`'.implode('`,`',array_keys($values)).'`) VALUES('.implode(',',array_fill(0,count($values),'?')).')');foreach(array_values($values) as $i=>$v)$q->bindValue($i+1,$v,is_int($v)||is_bool($v)?PDO::PARAM_INT:(is_null($v)?PDO::PARAM_NULL:PDO::PARAM_STR));$q->execute();return (int)$this->db->lastInsertId();
    }
    public function material($company,$id) {
        $this->permission($company);$r=$this->run('SELECT m.*,p.Producto,p.CodigoBarra FROM Cx_Material m JOIN Gen_Producto p ON p.IdProducto=m.IdProducto WHERE m.IdEmpresa=? AND m.IdProducto=? AND m.Activo=1 AND COALESCE(p.Anulado+0,0)=0',[$company,cxId($id)])->fetch(PDO::FETCH_ASSOC);if(!$r)throw new CxError('Material no disponible para esta empresa.',404);return $r;
    }
    public function materials($company,$warehouse=null) {
        $this->permission($company);if($warehouse)$this->reference($company,'ALMACEN',$warehouse);$rows=$this->run('SELECT m.*,p.Producto,p.CodigoBarra FROM Cx_Material m JOIN Gen_Producto p ON p.IdProducto=m.IdProducto WHERE m.IdEmpresa=? AND m.Activo=1 AND COALESCE(p.Anulado+0,0)=0 ORDER BY p.Producto',[$company])->fetchAll(PDO::FETCH_ASSOC);foreach($rows as &$r)if($warehouse)$r['stock']=$this->materialStock($company,$warehouse,$r['IdProducto']);unset($r);return $rows;
    }
    private function materialStock($company,$warehouse,$product) {
        $physical=$this->run('SELECT CAST(COALESCE(SUM(COALESCE(TotalCompras,0)-COALESCE(TotalVentas,0)),0) AS DECIMAL(18,6)) FROM Gen_Producto_Totales WHERE IdProducto=? AND IdAlmacen=?',[$product,$warehouse])->fetchColumn();
        $reserved=$this->run('SELECT COALESCE(SUM(CantidadNominal),0) FROM Cx_ReservaInsumo WHERE IdEmpresa=? AND IdAlmacen=? AND IdProducto=? AND Activo=1',[$company,$warehouse,$product])->fetchColumn();return ['fisico'=>$physical,'reservadoNominal'=>bcadd($reserved,'0',6),'disponible'=>bcsub($physical,$reserved,6)];
    }
    public function saveMaterial($company,array $p) {
        $this->operational($company,'ALMACEN');$type=cxChoice($p['tipo']??'',['CEMENTO','AGREGADO','ADITIVO','AGUA','OTRO'],'el tipo de insumo');$base=cxChoice($p['baseStock']??'',['SECA','SSS','HUMEDA','VOLUMEN'],'la base del stock');$unit=cxChoice($p['unidad']??'',['kg','L','m3'],'la unidad de stock');if(($unit==='kg'&&$base==='VOLUMEN')||($unit!=='kg'&&$base!=='VOLUMEN'))throw new CxError('Revise la base de stock y su unidad. No se convierte masa en volumen.');
        return $this->atomic($company,function()use($company,$p,$type,$base,$unit){return $this->idempotency($company,'MATERIAL',$p['idempotencia']??'',[$p,$this->user],function()use($company,$p,$type,$base,$unit){
            $id=empty($p['idProducto'])?null:cxId($p['idProducto']);$code=['kg'=>'KGM','L'=>'LTR','m3'=>'MTQ'][$unit];$measurement=$this->run('SELECT IdProductoMedicion FROM Gen_ProductoMedicion WHERE Codigo=? AND COALESCE(Anulado+0,0)=0 LIMIT 1',[$code])->fetchColumn();if(!$measurement)throw new CxError('Instale las unidades de materiales antes de continuar.');
            if($id){$product=$this->run('SELECT IdProducto,IdProductoMedicion,ControlaStock+0 AS ControlaStock FROM Gen_Producto WHERE IdProducto=? AND COALESCE(Anulado+0,0)=0',[$id])->fetch(PDO::FETCH_ASSOC);if(!$product||(int)$product['IdProductoMedicion']!==(int)$measurement||!(int)$product['ControlaStock'])throw new CxError('Seleccione un producto ERP con esa unidad y control de stock.');$owner=$this->run("SELECT IdEmpresa FROM Cx_ReferenciaERP WHERE Entidad='PRODUCTO' AND IdERP=?",[$id])->fetchColumn();if($owner!==false&&(int)$owner!==(int)$company)throw new CxError('Producto de otra empresa.',403);}
            else{$name=cxText($p['nombre']??'',255,true);$barcode=cxText($p['codigo']??'',100,true);if($this->run('SELECT IdProducto FROM Gen_Producto WHERE CodigoBarra=? LIMIT 1',[$barcode])->fetchColumn())throw new CxError('El código ya existe en el ERP; seleccione ese producto o use otro código.',409);$ids=[];foreach([['Gen_ProductoMarca','IdProductoMarca','ProductoMarca','INSUMOS WUANUKO'],['Gen_ProductoFormaFarmaceutica','IdProductoFormaFarmaceutica','ProductoFormaFarmaceutica','INSUMO'],['Gen_ProductoCategoria','IdProductoCategoria','ProductoCategoria','INSUMOS CONCRETERA']] as $t){$v=$this->run('SELECT '.$t[1].' FROM '.$t[0].' WHERE '.$t[2].'=? AND COALESCE(Anulado+0,0)=0 LIMIT 1',[$t[3]])->fetchColumn();if(!$v)throw new CxError('Falta instalar la clasificación de insumos.');$ids[$t[1]]=(int)$v;}$id=$this->erpInsert('Gen_Producto',array_merge($ids,['IdProductoMedicion'=>(int)$measurement,'Producto'=>$name,'CodigoBarra'=>$barcode,'ProductoModelo'=>'','PreciosPorProducto'=>'[]','ControlaStock'=>1,'Anulado'=>0,'PrecioContado'=>null,'PrecioCosto'=>null,'FechaReg'=>cxNow(),'UsuarioReg'=>$this->user,'Hash'=>bin2hex(random_bytes(16))]));$this->legacy[]=['id'=>$id,'tables'=>['Gen_Producto'=>'IdProducto']];}
            if($this->productOffer($company,$id))throw new CxError('Un producto comercial de concreto o servicio no se registra como insumo.');
            $this->run("INSERT IGNORE INTO Cx_ReferenciaERP(IdEmpresa,Entidad,IdERP,UsuarioReg,FechaReg) VALUES(?,'PRODUCTO',?,?,?)",[$company,$id,$this->user,cxNow()]);$this->run('INSERT INTO Cx_Material(IdEmpresa,IdProducto,Tipo,Unidad,BaseStock,UsuarioReg,FechaReg) VALUES(?,?,?,?,?,?,?)',[$company,$id,$type,$unit,$base,$this->user,cxNow()]);$this->audit($company,'material',$id,'VINCULAR',null,['unidad'=>$unit,'base'=>$base,'tipo'=>$type]);return ['id'=>$id];
        });});
    }
    public function findSuppliers($company,$query) {
        $this->operational($company,'ALMACEN');$query=cxText($query,120,true);if(mb_strlen($query)<2)throw new CxError('Escriba al menos dos letras o dígitos del proveedor.');return $this->run("SELECT p.IdProveedor,p.Proveedor,p.Ruc FROM Lo_Proveedor p LEFT JOIN Cx_ReferenciaERP r ON r.Entidad='PROVEEDOR' AND r.IdERP=p.IdProveedor WHERE COALESCE(p.Anulado+0,0)=0 AND (r.IdEmpresa IS NULL OR r.IdEmpresa=?) AND (p.Proveedor LIKE ? OR p.Ruc LIKE ?) ORDER BY p.Proveedor LIMIT 30",[$company,'%'.$query.'%','%'.$query.'%'])->fetchAll(PDO::FETCH_ASSOC);
    }
    public function receipts($company) {
        $this->permission($company);return $this->run('SELECT r.*,p.Proveedor,m.Anulado+0 AS MovimientoAnulado FROM Cx_RecepcionInsumo r LEFT JOIN Lo_Proveedor p ON p.IdProveedor=r.IdProveedor LEFT JOIN Lo_Movimiento m ON m.Hash=r.HashMovimiento WHERE r.IdEmpresa=? ORDER BY r.IdRecepcion DESC LIMIT 150',[$company])->fetchAll(PDO::FETCH_ASSOC);
    }
    private function reconcileReceipt(array $r,array $data) {
        $type=$this->run("SELECT IdMovimientoTipo FROM Lo_MovimientoTipo WHERE TipoMovimiento='RECEPCION INSUMOS CONCRETERA' AND Tipo=0 AND VaRegCompra=0 AND COALESCE(Anulado+0,0)=0 LIMIT 1")->fetchColumn();if(!$type)throw new CxError('Falta instalar el tipo de recepción física.');
        $header=$this->run('SELECT *,Anulado+0 AS EsAnulado FROM Lo_Movimiento WHERE IdMovimientoTipo=? AND IdProveedor=? AND Serie=? AND Numero=? LIMIT 1',[$type,$r['IdProveedor'],$r['Serie'],$r['Numero']])->fetch(PDO::FETCH_ASSOC);if(!$header)return null;
        $items=$this->run('SELECT * FROM Lo_MovimientoDetalle WHERE hashMovimiento=? ORDER BY IdProducto',[$header['Hash']])->fetchAll(PDO::FETCH_ASSOC);$expected=$data['productos'];usort($expected,function($a,$b){return $a['IdProducto']<=>$b['IdProducto'];});
        if((int)$header['EsAnulado']||(int)$header['IdAlmacenDestino']!==(int)$r['IdAlmacen']||count($items)!==count($expected))throw new CxError('El documento ya existe o cambió. Requiere revisión; no se creó otra entrada.',409);
        foreach($items as $i=>$item)if((int)$item['IdProducto']!==$expected[$i]['IdProducto']||bccomp((string)$item['Cantidad'],$expected[$i]['cantidad'],4)!==0||strpos((string)$item['Descripcion'],'[CXREC:'.$r['IdRecepcion'].']')!==0)throw new CxError('El documento pertenece a otro registro. No se duplicó la recepción.',409);
        return $header['Hash'];
    }
    public function retryReceipt($company,array $p) {
        $this->operational($company,'ALMACEN');$r=$this->run('SELECT * FROM Cx_RecepcionInsumo WHERE IdEmpresa=? AND IdRecepcion=?',[$company,cxId($p['id']??0)])->fetch(PDO::FETCH_ASSOC);if(!$r)throw new CxError('Recepción no disponible.',404);if($r['UsuarioReg']!==$this->user)throw new CxError('El reintento conservando el responsable debe hacerlo el usuario que registró la recepción.',403);$data=json_decode($r['Instantanea'],true);$items=[];foreach($data['productos'] as $c)$items[]=['idProducto'=>$c['IdProducto'],'cantidad'=>$c['cantidad'],'precio'=>$c['CostoPendiente']?'':$c['precio'],'loteReferencia'=>$c['Descripcion']];return $this->receiveMaterials($company,['idAlmacen'=>$data['almacen'],'idProveedor'=>$data['proveedor']['IdProveedor'],'serie'=>$data['serie'],'numero'=>$data['numero'],'fecha'=>$data['fecha'],'partidas'=>$items,'idempotencia'=>$r['Clave']]);
    }
    public function receiveMaterials($company,array $p) {
        $this->operational($company,'ALMACEN');$warehouse=$this->reference($company,'ALMACEN',$p['idAlmacen']??0);$supplier=cxId($p['idProveedor']??0);$sup=$this->run('SELECT IdProveedor,Proveedor,Ruc FROM Lo_Proveedor WHERE IdProveedor=? AND COALESCE(Anulado+0,0)=0',[$supplier])->fetch(PDO::FETCH_ASSOC);if(!$sup)throw new CxError('Seleccione un proveedor activo del ERP.');
        $series=cxText($p['serie']??'',100,true);$number=cxId($p['numero']??0);if($number>2147483647)throw new CxError('Número de documento fuera de rango.');$date=cxDateTime($p['fecha']??'');if($date>cxNow())throw new CxError('No registre una recepción física futura.');$key=cxText($p['idempotencia']??'',100,true);if(!preg_match('/^[A-Za-z0-9_-]{8,100}$/D',$key))throw new CxError('Clave de reintento inválida.');
        $items=$p['partidas']??[];if(!is_array($items)||!count($items)||count($items)>100)throw new CxError('Agregue entre 1 y 100 materiales.');$rows=[];$seen=[];foreach($items as $i){$material=$this->material($company,$i['idProducto']??0);$id=(int)$material['IdProducto'];if(isset($seen[$id]))throw new CxError('Unifique las cantidades del material repetido.');$seen[$id]=true;$cost=isset($i['precio'])&&$i['precio']!==''?cxDec($i['precio'],2):null;$rows[]=['IdProducto'=>$id,'cantidad'=>cxDec($i['cantidad']??'',2,true),'precio'=>$cost??'0','CostoPendiente'=>$cost===null,'Unidad'=>$material['Unidad'],'BaseStock'=>$material['BaseStock'],'Descripcion'=>cxText($i['loteReferencia']??'',250)];}
        $payload=['almacen'=>$warehouse,'proveedor'=>$sup,'serie'=>$series,'numero'=>$number,'fecha'=>$date,'productos'=>$rows,'usuario'=>$this->user];$hash=cxHash($payload);$lock='cx_recep_'.substr(hash('sha256',$company.$key),0,40);if((int)$this->run('SELECT GET_LOCK(?,5)',[$lock])->fetchColumn()!==1)throw new CxError('Otra sesión está confirmando esta recepción. Reintente.',409);
        try{
            $r=$this->atomic($company,function()use($company,$supplier,$warehouse,$series,$number,$payload,$key,$hash){$owner=$this->run("SELECT IdEmpresa FROM Cx_ReferenciaERP WHERE Entidad='PROVEEDOR' AND IdERP=? FOR UPDATE",[$supplier])->fetchColumn();if($owner!==false&&(int)$owner!==(int)$company)throw new CxError('Proveedor vinculado a otra empresa.',403);$this->run("INSERT IGNORE INTO Cx_ReferenciaERP(IdEmpresa,Entidad,IdERP,UsuarioReg,FechaReg) VALUES(?,'PROVEEDOR',?,?,?)",[$company,$supplier,$this->user,cxNow()]);$r=$this->run('SELECT * FROM Cx_RecepcionInsumo WHERE IdEmpresa=? AND Clave=? FOR UPDATE',[$company,$key])->fetch(PDO::FETCH_ASSOC);if($r){if(!hash_equals($r['Huella'],$hash))throw new CxError('Esta clave ya se usó con otros datos de recepción.',409);return $r;}$this->run('INSERT INTO Cx_RecepcionInsumo(IdEmpresa,Clave,Huella,IdAlmacen,IdProveedor,Serie,Numero,Instantanea,UsuarioReg,FechaReg) VALUES(?,?,?,?,?,?,?,?,?,?)',[$company,$key,$hash,$warehouse,$supplier,$series,$number,cxJson($payload),$this->user,cxNow()]);return $this->run('SELECT * FROM Cx_RecepcionInsumo WHERE IdRecepcion=?',[$this->db->lastInsertId()])->fetch(PDO::FETCH_ASSOC);});
            if($r['Estado']==='REGISTRADA')return ['id'=>$r['IdRecepcion'],'hash'=>$r['HashMovimiento'],'estado'=>'REGISTRADA'];$movement=$this->reconcileReceipt($r,$payload);
            if(!$movement){require_once __DIR__.'/ErpMovement.php';$type=$this->run("SELECT IdMovimientoTipo FROM Lo_MovimientoTipo WHERE TipoMovimiento='RECEPCION INSUMOS CONCRETERA' AND VaRegCompra=0 AND Tipo=0 AND COALESCE(Anulado+0,0)=0 LIMIT 1")->fetchColumn();$products=$rows;foreach($products as &$i)$i['Descripcion']='[CXREC:'.$r['IdRecepcion'].'] '.$i['Descripcion'];unset($i);$request=new CxMovementRequest(['movimiento'=>['movimientoTipo'=>['IdMovimientoTipo'=>$type],'almacenDestino'=>['IdAlmacen'=>$warehouse],'proveedor'=>['IdProveedor'=>$supplier],'Serie'=>$series,'Numero'=>$number,'MovimientoFecha'=>$date,'FechaStock'=>$date,'TipoCambio'=>1,'Moneda'=>'PEN','EsCredito'=>0,'alterarProductos'=>false,'user'=>$this->user],'productos'=>$products]);$response=imcSaveMovement($this->db,$request,new CxMovementResponse());if(empty($response->data['ok']))throw new CxError($response->data['error']??'No se pudo guardar el ingreso.',$response->status>=400?$response->status:422);$movement=$this->reconcileReceipt($r,$payload);if(!$movement)throw new CxError('Revise la recepción; no se pudo conciliar su movimiento.',409);}
            return $this->atomic($company,function()use($company,$r,$movement,$payload){$this->run("UPDATE Cx_RecepcionInsumo SET Estado='REGISTRADA',HashMovimiento=?,Error=NULL WHERE IdEmpresa=? AND IdRecepcion=?",[$movement,$company,$r['IdRecepcion']]);$this->audit($company,'recepcion',$r['IdRecepcion'],'INGRESAR_ERP',null,['hashMovimiento'=>$movement,'materiales'=>$payload['productos'],'area'=>'ALMACEN']);return ['id'=>$r['IdRecepcion'],'hash'=>$movement,'estado'=>'REGISTRADA'];});
        }finally{$this->run('SELECT RELEASE_LOCK(?)',[$lock]);}
    }
}
